-- Bootstrap empty databases; existing installations keep their data and audit column names.
BEGIN;
CREATE TABLE IF NOT EXISTS public."Menus" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DisplayName" text NULL,
    "Description" text NULL,
    "Icon" text NULL,
    "Number" integer NOT NULL,
    "Url" text NULL,
    "Component" text NULL,
    "ControllerName" text NULL,
    "ActionName" text NULL,
    "LinkTarget" text NULL,
    "ParentId" integer NOT NULL,
    "IsDisplay" boolean NOT NULL,
    "IsAction" boolean NOT NULL,
    "IsDeleted" boolean NOT NULL,
    "CreatedBy" text NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "UpdatedBy" text NULL,
    "UpdatedAt" timestamp without time zone NULL
);
CREATE TABLE IF NOT EXISTS public."RoleMenu" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RoleId" uuid NOT NULL,
    "MenuId" integer NOT NULL,
    "IsDeleted" boolean NOT NULL,
    "CreatedBy" text NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "UpdatedBy" text NULL,
    "UpdatedAt" timestamp without time zone NULL
);
COMMIT;
